L28_1.m_Talk_KOREA = "\237\156\180. \235\167\136\236\157\140\236\157\180 \236\149\132\237\148\132\235\132\164. \235\130\180 \235\167\136\236\157\140\235\143\132 \236\157\180\235\159\176\235\141\176, \234\184\128\235\166\176\235\139\164 \235\132\140 \236\150\188\235\167\136\235\130\152 \235\167\136\236\157\140\236\157\180 \236\176\162\236\150\180\236\167\136\234\185\140?"
L28_1.m_fTalkTime = 0.03
L28_1.m_Talk_JPN = "\227\129\181\227\129\134\227\128\130\230\130\178\227\129\151\227\129\132\227\130\143\227\129\173\227\128\130\231\167\129\227\129\167\227\130\130\227\129\147\227\129\134\227\129\170\227\129\174\227\129\171\227\128\129\227\130\176\227\131\170\227\131\179\227\131\128\227\129\174\230\130\178\227\129\151\227\129\191\227\129\175\227\129\169\227\130\140\227\129\187\227\129\169\227\129\139\227\128\130"
L28_1.m_Talk_ENG = "Whew... It pains me to see her like this. You must be heartbroken, Glinda."
L28_1.m_Talk_TWN = "\229\147\128\239\188\140\231\156\159\228\187\164\228\186\186\229\191\131\231\150\188\239\188\140\230\136\145\233\131\189\229\183\178\231\182\147\233\128\153\233\186\188\233\155\163\233\129\142\239\188\140\230\160\188\231\144\179\233\129\148\228\189\160\230\135\137\232\169\178\230\155\180\229\191\131\231\162\142\229\144\167\239\188\159"
L28_1.m_Talk_THA = "\224\185\128\224\184\174\224\185\137\224\184\173... \224\185\128\224\184\171\224\185\135\224\184\153\224\185\128\224\184\152\224\184\173\224\185\129\224\184\154\224\184\154\224\184\153\224\184\181\224\185\137\224\185\129\224\184\165\224\185\137\224\184\167\224\184\155\224\184\167\224\184\148\224\185\131\224\184\136\224\184\136\224\184\177\224\184\135 \224\185\128\224\184\152\224\184\173\224\185\128\224\184\173\224\184\135\224\184\129\224\185\135\224\184\132\224\184\135\224\185\128\224\184\170\224\184\181\224\184\162\224\185\131\224\184\136\224\184\161\224\184\178\224\184\129\224\184\170\224\184\180\224\184\153\224\184\176\224\184\129\224\184\165\224\184\180\224\184\153\224\184\148\224\184\178"
L28_1.m_Talk_VTN = "\195\148i... T\195\180i th\225\186\173t \196\145au l\195\178ng khi th\225\186\165y con b\195\169 th\225\186\191 n\195\160y. C\195\180 h\225\186\179n l\195\160 x\195\179t ru\225\187\153t l\225\186\175m, Glinda."
L28_1.m_Talk_SCN = "\229\145\188\227\128\130\231\156\159\230\152\175\228\188\164\229\191\131\229\145\162\227\128\130\232\191\158\230\136\145\233\131\189\229\166\130\230\173\164\229\191\131\231\151\155\239\188\140\230\131\179\229\191\133\230\160\188\231\144\179\232\190\190\228\189\160\229\191\131\233\135\140\229\176\177\230\155\180\229\138\160\233\154\190\229\143\151\228\186\134\227\128\130"
L28_1.m_Talk_DEU = "Puh. Es zerrei\195\159t mir das Herz, sie so zu sehen. Du musst untr\195\182stlich sein, Glinda."
L28_1.m_Talk_FRA = "Vraiment, \195\167a me fait mal de la voir comme \195\167a. Tu dois avoir le c\197\147ur bris\195\169, Glinda."
